display:flex;align-items:center;gap:9px}.live-dot{height:6px;width:6px;border-radius:50%;background:#df6245;box-shadow:0 0 12px #df6245}.hero h1,.select-head h2,.result-box h2,.pause-card h2{font:800 clamp(66px,8.5vw,120px)/.79 'Barlow Condensed',sans-serif;letter-spacing:-2px;margin:27px 0 22px}.hero h1 em,.select-head em,.result-box em,.pause-card em{font-style:normal;color:var(--gold)}.hero-copy{font-size:14px;line-height:1.8;color:#d0cec5;max-width:380px;margin:0 0 30px}.menu-actions{display:flex;gap:12px}.primary-btn,.secondary-btn{height:49px;min-width:176px;padding:0 20px;display:inline-flex;align-items:center;justify-content:space-between;font:700 11px 'DM Sans';letter-spacing:1.4px;border:1px solid var(--gold);transition:.18s}.primary-btn{background:var(--gold);color:#171711}.primary-btn span{font-size:17px;margin-left:24px}.primary-btn:hover{background:#f1ce7b;transform:translateY(-2px)}.secondary-btn{background:#1619169c;border-color:#aaa59778;color:#eee9dd}.secondary-btn:hover{border-color:var(--gold)}.mode-row{display:flex;gap:26px;margin-top:35px}.mode-row button{background:none;border:0;border-bottom:1px solid #ffffff3b;padding:0 0 11px;font-size:9px;font-weight:700;letter-spacing:1.4px;color:#d0cec5}.mode-row button span{color:var(--gold);margin-left:10px}.menu-footer{position:absolute;left:5.2%;right:5.2%;bottom:22px;display:flex;justify-content:space-between;font-size:8px;letter-spacing:1.6px;color:#a6a399}.menu-footer b{color:var(--gold);font-size:16px;margin-left:6px}.hidden{display:none!important}.overlay{position:absolute;inset:0;z-index:3;background:linear-gradient(110deg,#101210f2,#101210e8 60%,#1012109c);padding:95px 5.2% 32px;backdrop-filter:blur(3px)}.select-head{display:grid;grid-template-columns:1fr 3fr 1fr;align-items:center;margin-bottom:26px}.back-btn{justify-self:start;border:0;background:none;color:#c7c3b9;font-size:10px;letter-spacing:1.5px}.select-head h2{font-size:43px;line-height:1;margin:7px 0 0;letter-spacing:0}.step-label{justify-self:end;font:700 17px 'Barlow Condensed';color:var(--gold)}.step-label span{color:#777;margin:0 6px}.select-columns{height:calc(100% - 102px);display:grid;grid-template-columns:minmax(400px,1fr) minmax(265px,340px);gap:30px;max-width:1250px;margin:auto}.selection-panel{min-width:0}.selection-title{display:flex;justify-content:space-between;color:#c8c4ba;font-size:9px;font-weight:700;letter-spacing:1.5px;margin-bottom:12px}.selection-title span+span{color:#99958c}.character-grid{display:grid;grid-template-columns:repeat(3,minmax(100px,1fr));gap:9px}.character-tile{position:relative;min-height:112px;background:linear-gradient(140deg,#282a24,#161915);border:1px solid #ffffff1a;text-align:left;padding:9px;overflow:hidden;transition:.18s}.character-tile:before{content:'';position:absolute;inset:0;background:radial-gradient(ellipse at 75% 40%,var(--tone),transparent 67%);opacity:.2}.character-tile:hover,.character-tile.selected{border-color:var(--tone);transform:translateY(-2px)}.character-tile.selected:after{content:'✓';position:absolute;right:8px;top:6px;color:var(--tone);font-weight:bold}.tile-avatar{position:absolute;right:16px;top:12px;width:47px;height:62px;border-radius:25px 25px 4px 4px;background:linear-gradient(180deg,var(--tone),#222 78%);opacity:.8;clip-path:polygon(25% 0,75% 0,95% 22%,85% 43%,100% 100%,0 100%,15% 43%,5% 22%)}.tile-avatar:before{content:'';position:absolute;left:11px;top:-3px;width:25px;height:28px;border-radius:50%;background:#d5a77f;box-shadow:0 23px 0 5px var(--tone)}.tile-number{position:relative;font-size:8px;color:#c0bbad}.tile-name{position:absolute;left:9px;bottom:10px;right:4px;font:700 15px/1 'Barlow Condensed';letter-spacing:.3px;text-transform:uppercase}.tile-name small{display:block;color:#b9b4a9;font:500 8px 'DM Sans';margin-top:5px;letter-spacing:.5px}.fighter-card{border:1px solid #ffffff1c;background:#171a16c9;display:flex;flex-direction:column;min-height:0}.fighter-art{height:43%;min-height:130px;position:relative;overflow:hidden;display:grid;place-items:center;background:radial-gradient(ellipse at 50% 80%,#34372d,#191b18 70%)}.art-halo{position:absolute;width:175px;height:175px;border:1px solid #e5b85c25;border-radius:50%;box-shadow:0 0 0 25px #e5b85c08,0 0 0 50px #e5b85c05}.art-initial{position:relative;font:900 130px/.9 'Barlow Condensed';color:var(--tone,var(--gold));text-shadow:0 12px 30px #000;opacity:.9}.fighter-info{padding:18px 20px 20px;display:flex;flex:1;flex-direction:column}.fighter-info .eyebrow{font-size:8px}.fighter-info h3{font:800 32px/.95 'Barlow Condensed';margin:7px 0 9px}.fighter-info p{font-size:11px;color:#aaa79e;line-height:1.65;margin:0 0 14px}.stat-list{display:grid;gap:9px;margin:0 0 15px}.stat-list>div{display:grid;grid-template-columns:62px 1fr;align-items:center;font-size:8px;color:#c3bfb5;letter-spacing:1px}.stat-track{height:3px;background:#ffffff20}.stat-track i{height:100%;display:block;background:var(--gold)}.confirm-btn{width:100%;min-width:0;margin-top:auto}.confirm-btn:disabled{opacity:.42;cursor:not-allowed;transform:none}.fight-top{position:absolute;top:25px;left:6%;right:6%;display:grid;grid-template-columns:1fr 100px 1fr;gap:20px;align-items:start}.combatant{padding-top:7px}.nameplate{display:flex;gap:10px;align-items:center;font:700 15px 'Barlow Condensed';letter-spacing:1.2px;margin-bottom:8px}.enemy .nameplate{justify-content:flex-end}.side-tag{font:700 9px 'DM Sans';color:#191a14;background:var(--gold);padding:4px 6px}.health-shell{height:13px;background:#1a1c19;border:1px solid #e8dfc688;padding:2px;clip-path:polygon(0 0,100% 0,98% 100%,0 100%)}.health-fill{height:100%;width:100%;background:linear-gradient(90deg,#b99345,#eec970);transition:width .2s}.enemy .health-fill{margin-left:auto;background:linear-gradient(90deg,#e7775c,#ba413d)}.meter{height:3px;background:#ffffff1a;margin-top:5px}.meter i{height:100%;width:0;display:block;background:#f5f0e5;transition:width .2s}.round-info{text-align:center;background:#101210a9;border:1px solid #ffffff2a;padding:7px 5px}.round-info span,.round-info small{display:block;font-size:7px;letter-spacing:1.3px;color:#c5b99c}.round-info strong{display:block;font:800 30px/.95 'Barlow Condensed';color:var(--paper);margin:2px}.fight-message{position:absolute;top:28%;left:0;right:0;text-align:center;font:900 clamp(36px,6vw,72px)/1 'Barlow Condensed';letter-spacing:4px;color:var(--gold);text-shadow:0 4px 25px #000;pointer-events:none;opacity:0;transition:opacity .2s}.fight-message.show{opacity:1}.pause-button{position:absolute;right:25px;top:110px;border:1px solid #ffffff55;background:#111a;color:#eee;width:36px;height:36px}.control-hint{position:absolute;bottom:24px;left:50%;transform:translateX(-50%);white-space:nowrap;color:#e3ddcf;font-size:9px;letter-spacing:1.2px;text-shadow:0 2px 6px #000}.control-hint b{color:var(--gold);margin:0 8px}.touch-controls{display:none;position:absolute;inset:auto 16px 25px;justify-content:space-between;align-items:end;pointer-events:none}.touch-stick{height:115px;width:115px;border:1px solid #ffffff55;border-radius:50%;background:#171a1880;display:grid;place-items:center;pointer-events:auto;touch-action:none}.touch-stick span{width:39px;height:39px;background:#c4aa6b8c;border:1px solid #fff8;border-radius:50%}.touch-actions{display:grid;grid-template-columns:repeat(3,55px);gap:7px;pointer-events:auto}.touch-actions button{height:45px;border:1px solid #ffffff88;border-radius:50%;background:#171a18c9;font:700 8px 'DM Sans';touch-action:none}.touch-actions button[data-action="special"]{background:#c9a34d;color:#181710}.result,.pause-card{display:flex;align-items:center;justify-content:center;text-align:center}.result-box,.pause-card{max-width:500px;margin:auto}.result-box .eyebrow,.pause-card .eyebrow{justify-content:center}.result-box h2,.pause-card h2{font-size:76px;margin:20px 0 10px}.result-box p,.pause-card p{color:#c3bfb5;font-size:14px;margin:0 0 28px}.result-actions{display:flex;justify-content:center;gap:10px}.pause-card{display:flex;flex-direction:column;align-items:center;justify-content:center}.pause-card .secondary-btn{margin-top:10px;justify-content:center}.toast{position:absolute;z-index:8;top:18%;left:50%;transform:translate(-50%,-10px);opacity:0;transition:.25s;background:#181b18e8;border:1px solid #e5b85c77;padding:10px 16px;color:#f4ead1;font-size:11px;letter-spacing:.6px;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}@keyframes rise{from{opacity:0;transform:translateY(15px)}to{opacity:1;transform:translateY(0)}}
@media(max-width:850px){.topbar{padding:17px 5%}.edition{display:none}.screen{padding:95px 8% 50px;background:linear-gradient(90deg,#101210eb,#101210a9 65%,#10121056)}.hero h1{font-size:clamp(62px,13vw,100px)}.overlay{padding:85px 4% 18px}.select-columns{grid-template-columns:1fr 255px;gap:15px}.character-grid{gap:6px}.character-tile{min-height:95px;padding:7px}.tile-avatar{right:7px;transform:scale(.84);transform-origin:top right}.tile-name{font-size:13px;left:7px;bottom:8px}.fighter-info{padding:14px}.fighter-info h3{font-size:28px}.select-head{grid-template-columns:.7fr 3fr .5fr}.select-head h2{font-size:35px}.touch-controls{display:flex}.control-hint{display:none}}
