}.round-info{padding:5px 2px}.round-info span,.round-info small{font-size:6px}.round-info strong{font-size:23px}.pause-button{right:12px;top:88px;width:31px;height:31px}.touch-controls{inset:auto 12px 18px}.touch-stick{width:95px;height:95px}.touch-stick span{width:34px;height:34px}.touch-actions{grid-template-columns:repeat(3,46px);gap:5px}.touch-actions button{height:40px;font-size:7px}.result-box h2,.pause-card h2{font-size:60px}.result-actions{flex-direction:column;align-items:center}.result-actions button{min-width:190px}}

import * as THREE from 'three';
import './style.css';

const cast = [
 {name:'Narendra Modi',title:'The Campaigner',color:'#d97728',skin:'#bd8562',hair:'#e2ded1',style:'Rally Rhythm',bio:'A commanding presence with a campaign-ready dash and a crowd-stirring finisher.',stats:[78,63,74],coat:'saffron'},
 {name:'Yogi Adityanath',title:'The Saffron Sentinel',color:'#e4a536',skin:'#bd8663',hair:'#332b24',style:'Monastic Momentum',bio:'A steady, disciplined contender who turns patient defense into powerful counters.',stats:[73,58,87],coat:'robe'},
 {name:'Nitin Gadkari',title:'The Road Builder',color:'#6f9c4a',skin:'#bd876d',hair:'#4b3b32',style:'Highway Heavyweight',bio:'An unhurried powerhouse whose broad swings can move the whole debate along.',stats:[91,42,76],coat:'jacket'},
 {name:'Ravi Kishan',title:'The Showstopper',color:'#a554b5',skin:'#b57b5c',hair:'#28211f',style:'Cinema Combo',bio:'Big stage energy, quick footwork and a flair for dramatic finishing flourishes.',stats:[66,89,55],coat:'vest'},
 {name:'Lalu Prasad Yadav',title:'The Crowd Favorite',color:'#bb5450',skin:'#a8735b',hair:'#d6cdbd',style:'Railway Rumble',bio:'A veteran showman with surprising resilience and a knack for turning momentum.',stats:[70,52,94],coat:'kurta'},
 {name:'Rahul Gandhi',title:'The Long Marcher',color:'#5688bd',skin:'#c99273',hair:'#322923',style:'People’s Pace',bio:'An endurance-minded challenger who keeps moving and finds openings in the rush.',stats:[59,84,69],coat:'white'},
 {name:'Mamata Banerjee',title:'The Street-Fighting Poet',color:'#4ca8a3',skin:'#bd896a',hair:'#26221f',style:'Hurricane Hustle',bio:'Fast, fearless and difficult to pin down, with a whirlwind of quick counter-moves.',stats:[62,96,59],coat:'sari'},
 {name:'Mahatma Gandhi',title:'The Peaceful Persuader',color:'#e7d8ad',skin:'#976b51',hair:'#d6c8ad',style:'Satyagraha',bio:'A playful historical-inspired nonviolent contender. Wins through gentle persuasion, not punches.',stats:[46,72,100],coat:'dhoti',peaceful:true},
 {name:'Donald Trump',title:'The Deal Maker',color:'#4d75ae',skin:'#dda678',hair:'#e5b544',style:'Art of the Deal',bio:'A brash showman who thrives on big entrances, bold feints and headline-grabbing specials.',stats:[86,57,60],coat:'suit'}
];
const arenas=[{name:'Lok Sabha Lights',wall:'#35362c',floor:'#423629',trim:'#c69b50'},{name:'Jaipur Debate Hall',wall:'#49332e',floor:'#50352b',trim:'#e2a958'},{name:'Midnight Committee',wall:'#202d35',floor:'#333b3d',trim:'#5fb1a5'}];
const byId=id=>document.getElementById(id); const menu=byId('menu'),select=byId('select'),fightUI=byId('fight-ui'),result=byId('result'),pausePanel=byId('pause');
const canvas=byId('game');const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;
const scene=new THREE.Scene();scene.background=new THREE.Color('#171a18');scene.fog=new THREE.Fog('#171a18',18,42);
const camera=new THREE.PerspectiveCamera(42,innerWidth/innerHeight,.1,100);camera.position.set(0,8.5,15.5);camera.lookAt(0,1.3,0);
scene.add(new THREE.HemisphereLight('#fff1d2','#292923',2));const key=new THREE.DirectionalLight('#ffdfaa',3.3);key.position.set(-5,9,7);key.castShadow=true;key.shadow.mapSize.set(1024,1024);key.shadow.camera.left=-12;key.shadow.camera.right=12;key.shadow.camera.top=12;key.shadow.camera.bottom=-12;scene.add(key);const rim=new THREE.DirectionalLight('#7a9ac4',2.2);rim.position.set(5,5,-7);scene.add(rim);
const mat=(color,rough=.75,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});const arenaGroup=new THREE.Group();scene.add(arenaGroup);
function box(parent,w,h,d,m,x,y,z,rx=0,ry=0,rz=0){const o=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),m);o.position.set(x,y,z);o.rotation.set(rx,ry,rz);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o}
function sphere(parent,r,m,x,y,z,sx=1,sy=1,sz=1){const o=new THREE.Mesh(new THREE.SphereGeometry(r,16,12),m);o.position.set(x,y,z);o.scale.set(sx,sy,sz);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o}
function buildArena(index=0){arenaGroup.clear();const a=arenas[index];scene.background=new THREE.Color(a.wall);scene.fog.color.set(a.wall);const floor=mat(a.floor,.55),wood=mat('#62462e',.38),gold=mat(a.trim,.32,.5),dark=mat('#24251f'),seat=mat('#66523a');box(arenaGroup,23,.4,22,floor,0,-.25,0);box(arenaGroup,13,.22,10,wood,0,.02,0);for(let z=-4.5;z<=4.6;z+=1.5)box(arenaGroup,12,.06,.035,gold,0,.14,z);for(let x=-5.8;x<=5.9;x+=1.45)box(arenaGroup,.035,.06,9.3,gold,x,.14,0);
 box(arenaGroup,9,3,.4,dark,0,1.5,-8.7);for(let i=0;i<5;i++){box(arenaGroup,8.6-i*.7,.35,.55,wood,0,.55+i*.43,-7.2+i*.65);for(let j=0;j<12;j++){const c=new THREE.Color().setHSL((j*.14+i*.08)%1,.3,.45);const body=mat(c);sphere(arenaGroup,.17,body,-3.9+j*.7,.97+i*.42,-7.25+i*.65,.75,1, .6);sphere(arenaGroup,.12,mat('#b88967'),-3.9+j*.7,1.22+i*.42,-7.25+i*.65,.8,1,.7)}}
 for(const side of [-1,1]){box(arenaGroup,.28,4,18,wood,side*7.5,1.9,-1);for(let z=-7;z<7;z+=1.5){box(arenaGroup,2.4,.28,.8,seat,side*5.9,.55,z);box(arenaGroup,2.4,.3,.3,seat,side*5.9,.85,z-.2);for(let n=0;n<3;n++){sphere(arenaGroup,.14,mat(['#b5795c','#b4a07b','#627f70'][(n+z+9)%3|0]),side*(5.2+n*.65),1.18,z,.75,1.3,.7)}}}
 box(arenaGroup,3,.48,1.5,wood,0,.75,-6);box(arenaGroup,2.6,.18,1.2,gold,0,1.06,-6);box(arenaGroup,.22,1.4,.24,gold,0,1.8,-6.5);box(arenaGroup,.8,.08,.28,gold,0,2.55,-6.5);
 for(let x=-5;x<=5;x+=2.5){const light=new THREE.PointLight('#ffd18c',22,7);light.position.set(x,5,-4);arenaGroup.add(light);sphere(arenaGroup,.16,mat('#ffe3a3',.25,0),x,5,-4,.8,.5,.8)}
 // Brass rail, ornamental pillars, and subtle circular floor motif.
 for(const z of [-5.5,5.5])box(arenaGroup,13,.13,.13,gold,0,1.35,z);for(const x of [-6.4,6.4])for(const z of [-6,0,6]){box(arenaGroup,.28,4,.28,gold,x,1.9,z);sphere(arenaGroup,.25,gold,x,4,z,1,1.15,1)}
}
buildArena();
function makeFighter(data,side){const root=new THREE.Group();scene.add(root);const body=new THREE.Group();root.add(body);const skin=mat(data.skin),cloth=mat(data.color,.65),pants=mat(data.coat==='dhoti'?'#eee8d8':data.coat==='white'?'#e7e2d7':'#292b2a'),hair=mat(data.hair),shoe=mat('#292723'),gold=mat('#d1ad61',.35,.4);const parts={body,arms:[],legs:[]};
 sphere(body,.34,cloth,0,1.25,0,.85,1.08,.55);box(body,.52,.52,.37,cloth,0,1.32,0);sphere(body,.23,skin,0,1.91,0,.9,1.12,.88);sphere(body,.245,hair,0,2.08,-.015,1,.48,.95);sphere(body,.045,mat('#27211c'),-.09,1.94,.205,.7,.5,.4);sphere(body,.045,mat('#27211c'),.09,1.94,.205,.7,.5,.4);box(body,.12,.028,.08,mat('#422d24'),0,1.83,.21);
 if(data.coat==='saffron'||data.coat==='robe'||data.coat==='dhoti'){const sash=box(body,.18,.78,.4,data.coat==='dhoti'?mat('#d9ceaf'):gold,.12,1.35,.22,0,0,-.22);if(data.coat==='dhoti'){box(body,.55,.42,.4,mat('#e8dfc9'),0,.92,0);box(body,.2,.3,.21,skin,.42,1.4,0);box(body,.2,.3,.21,skin,-.42,1.4,0)}}
 if(data.coat==='sari'){box(body,.58,.66,.42,mat('#f2eee2'),0,1.13,0);box(body,.14,.72,.44,cloth,.23,1.35,.03,0,0,-.12);sphere(body,.27,hair,0,2.02,-.05,1.1,.4,1)}if(data.coat==='suit'){box(body,.59,.65,.42,mat('#244064'),0,1.33,0);box(body,.1,.4,.04,mat('#eee9dc'),0,1.28,.24);sphere(body,.3,hair,.02,2.11,-.04,1.05,.34,1)}if(data.coat==='vest'){box(body,.54,.42,.4,mat('#2a2827'),0,1.35,0)}
 for(const s of [-1,1]){const arm=new THREE.Group();arm.position.set(s*.38,1.57,0);body.add(arm);sphere(arm,.15,cloth,0,-.18,0,.9,1.7,.9);sphere(arm,.13,skin,0,-.51,.02);parts.arms.push(arm);const leg=new THREE.Group();leg.position.set(s*.18,.83,0);body.add(leg);box(leg,.18,.48,.2,pants,0,-.19,0);box(leg,.2,.12,.34,shoe,0,-.44,.07);parts.legs.push(leg)}
 // Briefcase lapel / robe borders / symbolic details.
 if(data.coat==='suit')box(body,.16,.12,.08,gold,.19,1.47,.24);if(data.coat==='saffron'||data.coat==='robe')box(body,.04,.62,.03,gold,-.15,1.36,.215);
