let mode='quick',arenaIndex=0,chosen=[],players=[],running=false,paused=false,elapsed=0,round=1,keys={},touchMove={x:0,z:0},audioOn=true,audioCtx=null,lastTime=0,storyWins=0,tournamentWins=0,viewAngle=0;

const grid=byId('character-grid');let activePick=0;function renderGrid(){grid.innerHTML='';cast.forEach((c,i)=>{const b=document.createElement('button');b.className='character-tile';b.style.setProperty('--tone',c.color);b.innerHTML=`<span class="tile-number">0${i+1}</span><span class="tile-avatar"></span><span class="tile-name">${c.name}<small>${c.style}</small></span>`;b.onclick=()=>{activePick=i;document.querySelectorAll('.character-tile').forEach(x=>x.classList.remove('active'));b.classList.add('active');showFighter(c);byId('confirm-pick').disabled=chosen.includes(i);};grid.append(b)});}
function showFighter(c){byId('fighter-name').textContent=c.name.toUpperCase();byId('fighter-role').textContent=c.title.toUpperCase();byId('fighter-bio').textContent=c.bio;byId('art-initial').textContent=c.name.split(' ').map(x=>x[0]).join('').slice(0,2);byId('fighter-art').style.setProperty('--tone',c.color);['power','agility','guard'].forEach((s,i)=>byId('stat-'+s).style.width=c.stats[i]+'%');}
renderGrid();
