byId('confirm-pick').onclick=()=>{if(chosen.includes(activePick)){toast('Choose a different contender.');return}chosen.push(activePick);document.querySelectorAll('.character-tile')[activePick].classList.add('selected');byId('selected-count').textContent=`${chosen.length} / 2 SELECTED`;if(chosen.length===1){if(mode==='local'){byId('pick-label').textContent='PLAYER 2 · SELECT';byId('confirm-pick').textContent='SELECT OPPONENT →';toast('Player 2: choose your contender.')}else{let cpu=(activePick+4)%cast.length;while(cpu===activePick)cpu=(cpu+1)%cast.length;chosen.push(cpu);startFight();}}else startFight();};
// Light audio cues are synthesized locally; no external audio assets are required.
function sound(freq=180,duration=.08,type='sine',volume=.035){if(!audioOn)return;try{audioCtx??=new AudioContext();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(volume,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration)}catch{}}
byId('sound-toggle').onclick=()=>{audioOn=!audioOn;byId('sound-toggle').innerHTML=audioOn?'♫ <span>SOUND ON</span>':'♫ <span>SOUND OFF</span>';if(audioOn)sound(440)};
function startFight(){scene.remove(...players);players=[makeFighter(cast[chosen[0]],-1),makeFighter(cast[chosen[1]],1)];players[0].position.x=-2.15;players[1].position.x=2.15;players[0].rotation.y=0;players[1].rotation.y=Math.PI;players.forEach(p=>{p.userData.health=100;p.userData.stamina=100;p.userData.meter=0;p.userData.cool=0;p.userData.attack=0});byId('p1-name').textContent=cast[chosen[0]].name.toUpperCase();byId('p2-name').textContent=cast[chosen[1]].name.toUpperCase();byId('p1-health').style.width=byId('p2-health').style.width='100%';byId('p1-meter').style.width=byId('p2-meter').style.width='0%';round=mode==='story'?storyWins+1:mode==='tournament'?tournamentWins+1:1;byId('round-label').textContent=`ROUND ${String(round).padStart(2,'0')}`;elapsed=0;running=true;paused=false;showScreen('fight');message(mode==='training'?'TRAINING — TRY EVERY MOVE':'READY?');camera.position.set(0,8.5,15.5);}
let msgTimeout;function message(text){const e=byId('fight-message');e.textContent=text;e.classList.add('show');clearTimeout(msgTimeout);msgTimeout=setTimeout(()=>e.classList.remove('show'),1400)}
function setBlock(p,on){p.userData.block=on;p.userData.parts.body.rotation.x=on?-.2:0}
function attack(p,type){const u=p.userData;if(!running||paused||u.cool>0||u.dodge>0)return;if(type==='special'&&u.meter<100){toast('Build your momentum before unleashing a special.');return}if(type!=='block'&&u.stamina<8){toast('Catch your breath — stamina is low.');return}if(type==='block'){setBlock(p,true);return}if(type==='dodge'){u.dodge=.38;u.stamina=Math.max(0,u.stamina-10);u.parts.body.position.z=p.position.z+(u.side<0?.65:-.65);sound(270,.11,'triangle');return}
 const data=u.data;u.cool=type==='special'?.82:type==='kick'?.58:.35;u.attack=type==='special'?.55:type==='kick'?.4:.27;u.attackType=type;u.stamina=Math.max(0,u.stamina-(type==='special'?4:type==='kick'?13:8));u.meter=Math.min(100,u.meter+(type==='special'?0:17));if(type==='special')u.meter=0;u.combo++;p.userData.parts.arms[1].rotation.x=-1.05;sound(type==='special'?90:type==='kick'?115:165,.12,'sawtooth',.045);
 if(data.peaceful&&type!=='special'){u.attack*=.4;toast('A firm but entirely peaceful reminder.')}
}
function doHit(attacker,defender,type){const a=attacker.userData,d=defender.userData;const dist=attacker.position.distanceTo(defender.position);if(dist>2.25||a.attack<=0||a.attack>.16||a.hit===a.attack)return;if(d.dodge>0)return;const toward=(defender.position.x-attacker.position.x);if(d.block&&type!=='special'){d.stamina=Math.max(0,d.stamina-15);d.meter=Math.min(100,d.meter+12);a.hit=a.attack;message('BLOCKED!');sound(250,.07,'square',.025);return}
