}
function movePlayer(p,dx,dz,dt){const u=p.userData;if(!running||paused)return;const speed=(2.2+u.data.stats[1]/100*2.2)*(u.block?.35:1)*(u.dodge>0?2.4:1);p.position.x=THREE.MathUtils.clamp(p.position.x+dx*speed*dt,-5.7,5.7);p.position.z=THREE.MathUtils.clamp(p.position.z+dz*speed*dt,-3.5,4.2);const foe=players[1-players.indexOf(p)];if(foe)p.rotation.y=foe.position.x>p.position.x?0:Math.PI;}
function cpuThink(p,foe,dt){const u=p.userData;u.ai-=dt;const dist=p.position.distanceTo(foe.position);if(u.ai>0)return;u.ai=.22+Math.random()*.25;if(dist>2.2){movePlayer(p,foe.position.x>p.position.x?1:-1,foe.position.z>p.position.z?.3:foe.position.z<p.position.z?-.3:0,.14);if(Math.random()<.2)setBlock(p,false);return}const f=foe.userData;if(f.attack>0&&Math.random()<(.18+u.data.stats[2]/250)){setBlock(p,true);setTimeout(()=>setBlock(p,false),300);return}setBlock(p,false);const r=Math.random();if(u.meter>=100&&r<.18)attack(p,'special');else if(r<.46)attack(p,'punch');else if(r<.73)attack(p,'kick');else if(r<.83)attack(p,'dodge');else setBlock(p,true);}
function actionFor(player,action){if(!players[player])return;if(action==='block'){setBlock(players[player],true);return}attack(players[player],action)}
function endFight(winner){if(!running)return;running=false;const win=winner.userData.data;byId('result-title').innerHTML=`${win.name.split(' ')[0].toUpperCase()} <em>HOLDS THE FLOOR.</em>`;byId('result-subtitle').textContent=mode==='training'?'Practice session complete. Keep sharpening those arguments.':`${win.name} wins the debate — at least until the next recess.`;if(mode==='story'&&winner===players[0])storyWins++;if(mode==='tournament'&&winner===players[0])tournamentWins++;sound(520,.4,'sine',.04);setTimeout(()=>showScreen('result'),500)}
function togglePause(){if(!running)return;paused=!paused;showScreen(paused?'pause':'fight');if(!paused)lastTime=performance.now()}
byId('pause-button').onclick=togglePause;byId('resume').onclick=togglePause;byId('pause-menu').onclick=()=>{running=false;showScreen('menu')};byId('result-menu').onclick=()=>showScreen('menu');byId('rematch').onclick=()=>startFight();

const keyMap={KeyW:[0,-1],KeyS:[0,1],KeyA:[-1,0],KeyD:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1],ArrowLeft:[-1,0],ArrowRight:[1,0]};window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='Escape')togglePause();if(e.code==='KeyJ')attack(players[0],'punch');if(e.code==='KeyK')attack(players[0],'kick');if(e.code==='KeyL')actionFor(0,'block');if(e.code==='Space')attack(players[0],'dodge');if(e.code==='KeyI')attack(players[0],'special');if(e.code==='Numpad1')attack(players[1],'punch');if(e.code==='Numpad2')attack(players[1],'kick');if(e.code==='Numpad3')actionFor(1,'block');if(e.code==='Numpad0')attack(players[1],'dodge');if(e.code==='Numpad5')attack(players[1],'special')});window.addEventListener('keyup',e=>{keys[e.code]=false;if(e.code==='KeyL'&&players[0])setBlock(players[0],false);if(e.code==='Numpad3'&&players[1])setBlock(players[1],false)});
let stickPointer=null;const stick=byId('touch-stick');stick.addEventListener('pointerdown',e=>{stickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);updateStick(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===stickPointer)updateStick(e)});stick.addEventListener('pointerup',()=>{stickPointer=null;touchMove={x:0,z:0};stick.children[0].style.transform='translate(0,0)'});function updateStick(e){const r=stick.getBoundingClientRect(),x=(e.clientX-r.left-r.width/2)/(r.width*.34),y=(e.clientY-r.top-r.height/2)/(r.height*.34);touchMove={x:THREE.MathUtils.clamp(x,-1,1),z:THREE.MathUtils.clamp(y,-1,1)};stick.children[0].style.transform=`translate(${touchMove.x*25}px,${touchMove.z*25}px)`}
document.querySelectorAll('.touch-actions button').forEach(b=>{const action=b.dataset.action;b.addEventListener('pointerdown',e=>{e.preventDefault();actionFor(0,action)});if(action==='block'){b.addEventListener('pointerup',()=>players[0]&&setBlock(players[0],false));b.addEventListener('pointercancel',()=>players[0]&&setBlock(players[0],false))}});
byId('arena-cycle').onclick=()=>{arenaIndex=(arenaIndex+1)%arenas.length;buildArena(arenaIndex);byId('arena-cycle').innerHTML=`ARENA <span>↻</span> <b>${arenas[arenaIndex].name.toUpperCase()}</b>`;toast(`${arenas[arenaIndex].name} selected.`)};
let dragX=null;canvas.addEventListener('pointerdown',e=>{if(fightUI.classList.contains('hidden'))return;dragX=e.clientX});canvas.addEventListener('pointermove',e=>{if(dragX!==null){viewAngle=THREE.MathUtils.clamp(viewAngle+(e.clientX-dragX)*.004,-.55,.55);dragX=e.clientX}});window.addEventListener('pointerup',()=>dragX=null);
function animateFighter(p,dt,t){const u=p.userData,parts=u.parts;u.cool=Math.max(0,u.cool-dt);u.attack=Math.max(0,u.attack-dt);u.dodge=Math.max(0,u.dodge-dt);u.hit=Math.max(0,u.hit-dt);u.stamina=Math.min(100,u.stamina+dt*11);if(u.attack<=0){parts.arms.forEach(a=>a.rotation.x=THREE.MathUtils.damp(a.rotation.x,0,9,dt));parts.legs.forEach(l=>l.rotation.x=THREE.MathUtils.damp(l.rotation.x,0,8,dt))}else if(u.attackType==='punch'){parts.arms[1].rotation.x=-.8;parts.arms[1].rotation.z=-.2}else if(u.attackType==='kick'){parts.legs[1].rotation.x=-.9}
