function frame(now){requestAnimationFrame(frame);const dt=Math.min(.04,(now-lastTime)/1000||0);lastTime=now;const t=now/1000;if(running&&!paused){elapsed+=dt;if(mode!=='training'){const sec=Math.max(0,60-Math.floor(elapsed));byId('timer').textContent=String(sec).padStart(2,'0');if(sec===0)endFight(players[0].userData.health>=players[1].userData.health?players[0]:players[1])}for(let i=0;i<players.length;i++){const p=players[i],u=p.userData,foe=players[1-i];u.moveX=0;u.moveZ=0;if(i===0){const x=(keys.KeyD?1:0)-(keys.KeyA?1:0)+touchMove.x,z=(keys.KeyS?1:0)-(keys.KeyW?1:0)+touchMove.z;if(x||z){u.moveX=x;u.moveZ=z;movePlayer(p,x,z,dt)}}else if(mode==='local'){const x=(keys.ArrowRight?1:0)-(keys.ArrowLeft?1:0),z=(keys.ArrowDown?1:0)-(keys.ArrowUp?1:0);if(x||z){u.moveX=x;u.moveZ=z;movePlayer(p,x,z,dt)}}else cpuThink(p,foe,dt);animateFighter(p,dt,t);doHit(p,foe,u.attackType)}const mid=(players[0].position.x+players[1].position.x)/2;camera.position.x=THREE.MathUtils.damp(camera.position.x,mid*.22+viewAngle*5,2,dt);camera.lookAt(mid*.18,1.15,0)}else{for(const p of players)animateFighter(p,dt,t)}renderer.render(scene,camera)}requestAnimationFrame(frame);
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.7))});
// Initial silhouettes give the title screen a live, staged arena rather than an empty backdrop.
const showModels=[makeFighter(cast[0],-1),makeFighter(cast[6],-1),makeFighter(cast[8],-1)];showModels.forEach((p,i)=>{p.position.set(3.2+i*1.35,0,-1.2+i*.55);p.scale.setScalar(i===1?.92:1.04);p.rotation.y=-.35});
const originalStart=startFight;startFight=function(){showModels.forEach(p=>{p.visible=false});originalStart()};const oldMenu=byId('result-menu').onclick;byId('result-menu').onclick=()=>{running=false;players.forEach(p=>scene.remove(p));showModels.forEach(p=>p.visible=true);showScreen('menu')};byId('pause-menu').onclick=()=>{running=false;players.forEach(p=>scene.remove(p));showModels.forEach(p=>p.visible=true);showScreen('menu')};
// Prevent browser scrolling/zoom gestures from stealing mobile combat input.
document.addEventListener('touchmove',e=>{if(!fightUI.classList.contains('hidden'))e.preventDefault()},{passive:false});

