  arenaIndex = (arenaIndex + 1) % arenas.length;
  buildArena(arenaIndex);
  byId('arena-cycle').innerHTML = `ARENA <span>↻</span> <b>${arenas[arenaIndex].name.toUpperCase()}</b>`;
