29: function showScreen(id) {
30:   screens.forEach((screen) => {
31:     const el = byId(screen);
32:     if (el) el.classList.toggle('hidden', screen !== id);
33:   });
34:   byId('menu').classList.toggle('hidden', id !== 'menu');
35:   byId('app').classList.toggle('session-active', ['fight-ui', 'pause', 'result'].includes(id));
36: }
37: function toast(message) {
38:   const el = byId('toast');
39:   el.textContent = message;
40:   el.classList.add('visible');
41:   clearTimeout(toastTimer);
42:   toastTimer = setTimeout(() => el.classList.remove('visible'), 1800);
43: }
44: function tone(freq = 220, duration = .08, type = 'triangle', volume = .045) {
45:   if (!audioOn) return;
46:   try {
47:     audioContext ??= new AudioContext();
48:     if (audioContext.state === 'suspended') audioContext.resume();
49:     const osc = audioContext.createOscillator();
50:     const gain = audioContext.createGain();
51:     osc.type = type;
52:     osc.frequency.setValueAtTime(freq, audioContext.currentTime);
53:     gain.gain.setValueAtTime(volume, audioContext.currentTime);
54:     gain.gain.exponentialRampToValueAtTime(.001, audioContext.currentTime + duration);
55:     osc.connect(gain).connect(audioContext.destination);
56:     osc.start(); osc.stop(audioContext.currentTime + duration);
57:   } catch { /* Audio is optional; gameplay remains available without it. */ }
58: }
