60: function makeSelection() {
61:   const grid = byId('character-grid');
62:   grid.replaceChildren();
63:   cast.forEach((fighter, index) => {
64:     const button = document.createElement('button');
65:     button.className = 'character-tile';
66:     button.type = 'button';
67:     button.innerHTML = `<span class="tile-number">0${index + 1}</span><span class="tile-avatar" style="--avatar:${fighter.color};--skin:${fighter.skin};--hair:${fighter.hair}"></span><span class="tile-name">${fighter.name}<small>${fighter.title}</small></span>`;
68:     button.setAttribute('aria-label', `${fighter.name}, ${fighter.title}`);
69:     button.addEventListener('click', () => {
70:       highlighted = index;
71:       updateCard();
72:       tone(420, .055);
73:     });
74:     grid.append(button);
75:   });
76: }
77: function updateCard() {
78:   const fighter = cast[highlighted];
79:   byId('fighter-name').textContent = fighter.name;
80:   byId('fighter-role').textContent = fighter.title.toUpperCase();
81:   byId('fighter-bio').textContent = fighter.bio;
82:   byId('art-initial').textContent = fighter.name.split(' ').map((part) => part[0]).slice(0, 2).join('');
83:   byId('fighter-art').style.setProperty('--fighter-color', fighter.color);
84:   byId('stat-power').style.width = `${fighter.stats[0]}%`;
85:   byId('stat-agility').style.width = `${fighter.stats[1]}%`;
86:   byId('stat-guard').style.width = `${fighter.stats[2]}%`;
87:   document.querySelectorAll('.character-tile').forEach((el, i) => {
88:     el.classList.toggle('active', i === highlighted);
89:     el.classList.toggle('picked', selected.includes(i));
90:   });
91:   byId('selected-count').textContent = mode === 'local'
92:     ? `${selected.length} / 2 SELECTED`
93:     : `${selected.length} / 1 SELECTED`;
94:   byId('pick-label').textContent = mode === 'local' && selected.length === 1 ? 'PLAYER 2 · SELECT' : 'PLAYER 1 · SELECT';
95:   byId('confirm-pick').disabled = mode === 'local' ? selected.length >= 2 : selected.length >= 1;
96:   byId('confirm-pick').firstChild.textContent = mode === 'local' && selected.length === 1 ? 'SELECT PLAYER 2 ' : 'SELECT CONTENDER ';
97: }
98: function beginSelection(nextMode) {
99:   mode = nextMode;
100:   selected = [];
101:   highlighted = 0;
102:   byId('round-label').textContent = mode === 'training' ? 'PRACTICE' : 'ROUND 01';
103:   makeSelection();
104:   updateCard();
105:   showScreen('select');
106: }
