108: function updateHealth() {
109:   players.forEach((player, index) => {
110:     const u = player.userData;
111:     byId(`p${index + 1}-health`).style.width = `${Math.max(0, u.health)}%`;
112:     byId(`p${index + 1}-meter`).style.width = `${Math.min(100, u.meter)}%`;
113:   });
114: }
115: function fightOpponent() {
116:   if (mode === 'story') return cast[[1, 2, 3][storyWins % 3]];
117:   if (mode === 'tournament') return cast[(selected[0] + 1 + tournamentWins) % cast.length];
118:   const options = cast.map((_, i) => i).filter((i) => i !== selected[0]);
119:   return cast[options[Math.floor(Math.random() * options.length)]];
120: }
121: function startFight() {
122:   players.forEach((p) => scene.remove(p));
123:   const p1 = cast[selected[0] ?? 0];
124:   const p2 = mode === 'local' ? cast[selected[1] ?? 1] : fightOpponent();
125:   players = [makeFighter(p1, -1), makeFighter(p2, 1)];
126:   players[0].position.set(-2.15, 0, 0);
127:   players[1].position.set(2.15, 0, 0);
128:   if (showModels.length) showModels.forEach((p) => { p.visible = false; });
129:   elapsed = 0; paused = false; running = true; viewAngle = 0;
130:   byId('p1-name').textContent = p1.name.toUpperCase();
131:   byId('p2-name').textContent = p2.name.toUpperCase();
132:   byId('timer').textContent = mode === 'training' ? '∞' : '60';
133:   byId('round-label').textContent = mode === 'story' ? `STORY ${String(storyWins + 1).padStart(2, '0')}` : mode === 'tournament' ? `BRACKET ${String(tournamentWins + 1).padStart(2, '0')}` : mode === 'training' ? 'PRACTICE' : 'ROUND 01';
134:   byId('fight-message').textContent = mode === 'training' ? 'Practice your timing — your opponent will not be defeated.' : 'THE HOUSE IS IN SESSION';
135:   byId('control-hint').textContent = mode === 'local'
136:     ? 'P1 WASD · J PUNCH · K KICK · L GUARD · SPACE DODGE · I SPECIAL  /  P2 ARROWS · NUMPAD 1–5'
137:     : 'WASD MOVE  ·  J PUNCH  ·  K KICK  ·  L GUARD  ·  SPACE DODGE  ·  I SPECIAL';
138:   updateHealth();
139:   showScreen('fight-ui');
140:   tone(330, .18, 'sawtooth', .025);
141: }
142: function confirmSelection() {
143:   if (mode === 'local' && selected.length === 1) {
144:     if (highlighted === selected[0]) { toast('Choose a different contender for Player 2.'); return; }
145:     selected.push(highlighted);
146:     startFight();
147:     return;
148:   }
149:   if (!selected.length) selected.push(highlighted);
150:   if (mode === 'local' && selected.length < 2) { updateCard(); return; }
151:   startFight();
152: }
